const storageKey = "codexa-smoke-quote-board-3:favorites";
const quoteGrid = document.querySelector("#quoteGrid");
const emptyState = document.querySelector("#emptyState");
const favoriteCount = document.querySelector("#favoriteCount");
const filterButtons = document.querySelectorAll(".filter-button");

let activeFilter = "all";
let favoriteIds = loadFavorites();

function loadFavorites() {
  try {
    const parsed = JSON.parse(localStorage.getItem(storageKey) || "[]");
    return new Set(Array.isArray(parsed) ? parsed : []);
  } catch {
    return new Set();
  }
}

function saveFavorites() {
  localStorage.setItem(storageKey, JSON.stringify([...favoriteIds]));
}

function renderQuotes() {
  const visibleQuotes = activeFilter === "favorites"
    ? quotes.filter((quote) => favoriteIds.has(quote.id))
    : quotes;

  quoteGrid.innerHTML = visibleQuotes.map((quote) => {
    const isFavorite = favoriteIds.has(quote.id);
    const star = isFavorite ? "★" : "☆";
    const pressed = isFavorite ? "true" : "false";
    const buttonLabel = isFavorite ? "Remove from favorites" : "Save to favorites";

    return `
      <article class="quote-card">
        <div>
          <p class="quote-text">“${quote.text}”</p>
          <p class="quote-author">— ${quote.author}</p>
        </div>
        <div class="card-footer">
          <span class="tag">${quote.tag}</span>
          <button class="favorite-button ${isFavorite ? "is-favorite" : ""}" type="button" data-id="${quote.id}" aria-pressed="${pressed}" aria-label="${buttonLabel}: ${quote.author}">
            ${star}
          </button>
        </div>
      </article>
    `;
  }).join("");

  favoriteCount.textContent = String(favoriteIds.size);
  emptyState.hidden = !(activeFilter === "favorites" && visibleQuotes.length === 0);
  quoteGrid.hidden = visibleQuotes.length === 0;
}

function setActiveFilter(nextFilter) {
  activeFilter = nextFilter;
  filterButtons.forEach((button) => {
    button.classList.toggle("is-active", button.dataset.filter === activeFilter);
  });
  renderQuotes();
}

quoteGrid.addEventListener("click", (event) => {
  const favoriteButton = event.target.closest(".favorite-button");

  if (!favoriteButton) {
    return;
  }

  const quoteId = favoriteButton.dataset.id;

  if (favoriteIds.has(quoteId)) {
    favoriteIds.delete(quoteId);
  } else {
    favoriteIds.add(quoteId);
  }

  saveFavorites();
  renderQuotes();
});

filterButtons.forEach((button) => {
  button.addEventListener("click", () => {
    setActiveFilter(button.dataset.filter);
  });
});

renderQuotes();
