{"type":"item.completed","item":{"id":"item_16","type":"command_execution","command":"/bin/zsh -lc "sed -n '1,220p' script.js"","aggregated_output":"const STORAGE_KEY = "codexa-smoke-quote-board-two:v1";

const seedQuotes = [
  {
    id: "seed-1",
    text: "The best way out is always through.",
    author: "Robert Frost",
    favorite: true
  },
  {
    id: "seed-2",
    text: "What you do every day matters more than what you do once in a while.",
    author: "Gretchen Rubin",
    favorite: false
  },
  {
    id: "seed-3",
    text: "Make it work, make it right, make it fast.",
    author: "Kent Beck",
    favorite: false
  }
];

const quoteGrid = document.querySelector("#quoteGrid");
const emptyState = document.querySelector("#emptyState");
const quoteForm = document.querySelector("#quoteForm");
const quoteText = document.querySelector("#quoteText");
const quoteAuthor = document.querySelector("#quoteAuthor");
const totalCount = document.querySelector("#totalCount");
const favoriteCount = document.querySelector("#favoriteCount");
const filterButtons = document.querySelectorAll(".filter-button");

let quotes = loadQuotes();
let activeFilter = "all";

render();

quoteForm.addEventListener("submit", (event) => {
  event.preventDefault();

  const text = quoteText.value.trim();
  const author = quoteAuthor.value.trim() || "Unknown";

  if (!text) {
    quoteText.focus();
    return;
  }

  quotes = [
    {
      id: createId(),
      text,
      author,
      favorite: false
    },
    ...quotes
  ];

  quoteForm.reset();
  quoteText.focus();
  saveQuotes();
  render();
});

filterButtons.forEach((button) => {
  button.addEventListener("click", () => {
    activeFilter = button.dataset.filter;
    render();
  });
});

quoteGrid.addEventListener("click", (event) => {
  const button = event.target.closest("button[data-action]");

  if (!button) {
    return;
  }

  const card = button.closest("[data-id]");
  const id = card.dataset.id;
  const action = button.dataset.action;

  if (action === "favorite") {
    quotes = quotes.map((quote) => (
      quote.id === id ? { ...quote, favorite: !quote.favorite } : quote
    ));
  }

  if (action === "delete") {
    quotes = quotes.filter((quote) => quote.id !== id);
  }

  saveQuotes();
  render();
});

function loadQuotes() {
  try {
    const stored = JSON.parse(localStorage.getItem(STORAGE_KEY));
    return Array.isArray(stored) && stored.length ? stored : seedQuotes;
  } catch {
    return seedQuotes;
  }
}

function saveQuotes() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(quotes));
}

function createId() {
  if (globalThis.crypto && typeof globalThis.crypto.randomUUID === "function") {
    return globalThis.crypto.randomUUID();
  }

  return `quote-${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

function render() {
  const visibleQuotes = activeFilter === "favorites"
    ? quotes.filter((quote) => quote.favorite)
    : quotes;

  totalCount.textContent = quotes.length;
  favoriteCount.textContent = quotes.filter((quote) => quote.favorite).length;
  emptyState.hidden = visibleQuotes.length > 0;

  filterButtons.forEach((button) => {
    button.classList.toggle("is-active", button.dataset.filter === activeFilter);
  });

  quoteGrid.innerHTML = visibleQuotes.map(createQuoteCard).join("");
}

function createQuoteCard(quote) {
  const favoriteLabel = quote.favorite ? "Remove from favorites" : "Save to favorites";

  return `
    <article class="quote-card" data-id="${escapeHtml(quote.id)}">
      <p class="quote-text">&ldquo;${escapeHtml(quote.text)}&rdquo;</p>
      <footer class="quote-meta">
        <span>${escapeHtml(quote.author)}</span>
        <span class="quote-actions">
          <button class="icon-button" type="button" data-action="favorite" aria-label="${favoriteLabel}" aria-pressed="${quote.favorite}">
            ${quote.favorite ? "★" : "☆"}
          </button>
          <button class="icon-button" type="button" data-action="delete" aria-label="Delete quote">
            ×
          </button>
        </span>
      </footer>
    </article>
  `;
}

function escapeHtml(value) {
  return String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
